solutions.naive:
class Solution:
    def getSkyline(self, buildings: list[list[int]]) -> list[list[int]]:
        xs = sorted(set([x for l, r, h in buildings for x in (l, r)]))
        ans = []
        for x in xs:
            height = 0
            for l, r, h in buildings:
                if l <= x < r and h > height:
                    height = h
            if not ans or ans[-1][1] != height:
                ans.append([x, height])
        return ans

