class Solution:
    def getSkyline(self, buildings: list[list[int]]) -> list[list[int]]:
        from bisect import insort, bisect_left
        events = []
        for l, r, h in buildings:
            events.append((l, -h))
            events.append((r, h))
        events.sort()
        active = [0]
        ans = []
        i = 0
        while i < len(events):
            x = events[i][0]
            while i < len(events) and events[i][0] == x:
                h = events[i][1]
                if h < 0:
                    insort(active, -h)
                else:
                    j = bisect_left(active, h)
                    active.pop(j)
                i += 1
            cur = active[-1]
            if not ans or ans[-1][1] != cur:
                ans.append([x, cur])
        return ans

